%[text] # Profiling simulation with Reducer Basic model
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] Run simulation using the `solverprofiler.profileModel` function. See the documentation about the function for details.
%[text] - [https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html](https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html) \
%[text] ## Set up
model_name = "HarnessModel_Reducer";
target_folder = fullfile(currentProject().RootFolder, "Components", "Reducer", "Model-Basic", "SimulationCases");
data_fullpath = fullfile(target_folder, "profiling_data.mat");
%[text] ## Run simulation normally
assert(isfolder(target_folder))
load_system(model_name);

% Close the Scope window to avoid getting the screenshot.
close_system(model_name + "/Measurement/Scope")

Reducer_Basic_params
loadLUTData_Reducer_Axle_FlipTorque
loadLUTData_Reducer_Motor_FlipTorque

sim_in = Simulink.SimulationInput(model_name);

sim_in = setModelParameter(sim_in, StopTime = "150");
%[text] Run simulation normally and plot results.
sim_out = sim(sim_in);
signals = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
varnames = string(signals.Properties.VariableNames);
for k = 1 : numel(varnames) %[output:group:5ac999e7]
  bevutil1.SignalUtil.plotTimedData(TimedData=signals, SignalName=varnames(k), FigureHeight=150); %[output:99f6da42] %[output:5bcb47b4] %[output:44e237ed] %[output:2e6111a9] %[output:1942f2ac] %[output:6cb37d56] %[output:268efd58] %[output:0555bb9d] %[output:08ebf114] %[output:82de972d] %[output:0a1b03fb] %[output:9717a1dc]
end  % for %[output:group:5ac999e7]
%%
%[text] ## Step size
fig = figure; %[output:8446333b]
fig.Position(3:4) = [800, 200];  % width, height %[output:8446333b]
bevutil1.SignalUtil.plotDifference(sim_out.tout, NewFigure=false, ParentAxes=axes(fig), ... %[output:group:8265929f] %[output:8446333b]
  YScale = "Log", Title="Step size", YUnitText="s", ... %[output:8446333b]
  XLabel="Time", XUnitText="s" ) %[output:group:8265929f] %[output:8446333b]
step_size_data = diff(sim_out.tout);
disp("Maximum step size: " + max(step_size_data)) %[output:41a659ab]
fprintf("Minimum step size: %e", min(step_size_data)) %[output:7a002d7d]
%%
%[text] ## Profiling simulation
%[text] Run profiling simulation using the Solver Profiler. See the [documentation](https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html) about the `solverprofiler.profileModel` function for details.
load_system(model_name)
result = solverprofiler.profileModel( ...
  model_name, ...
  DataFullFile = data_fullpath, ...
  OpenSP = "off", ... Set "on" to open the Solver Profiler after completing profiling.
  TimeOut = 10, ... in seconds. Stop the profiling simulation if the simulation does not make progress.
  StartTime = 0, ... Start time in seconds for profiling. Simulation starts from the model's StartTime which is usually 0.
  StopTime = 100, ... Stop time in seconds for simulation and profiling. The model's StopTime is not affected by this option.
  BufferSize = 50000, ... Maximum number of events to log.
  SaveStates = "on", ...
  SaveSimscapeStates = "on", ...
  SaveJacobian = "on", ...
  SaveZCSignals = "on" );
%[text] View the high-level summary of profiling result. See the [documentation](https://www.mathworks.com/help/simulink/slref/solverprofiler.profilemodel.html) for details.
%[text] - `tStart` - Start time in seconds for profiling. Can be different from simulation start time.
%[text] - `tStop` - Stop time in seconds for profiling. Can be different from simulation stop time.
%[text] - `absTol` - Absolute tolerance for the solver.
%[text] - `relTol` - Relative tolerance for the solver.
%[text] - `hMax` - Maximum step size.
%[text] - `hAverage` - Average size of steps taken by the solver.
%[text] - `steps` - Total number of time steps.
%[text] - `profileTime` - Elapsed time in seconds.
%[text] - `zcNumber` - Number of zero crossings detected.
%[text] - `resetNumber` - Number of solver resets that occurred.
%[text] - `jacobianNumber` - Number of times the solver updated the Jacobian matrix.
%[text] - `exceptionNumber` - Total number of solver exceptions that occurred. \
disp(result.summary) %[output:00be79dd]
%[text] Open the Solver Profiler with the saved session data.
%solverprofiler.exploreResult(char(data_fullpath))
